use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// Hosts this node is granted. The host enforces the same allowlist at the
/// boundary (a request outside it traps); this check runs first so that one
/// out-of-scope URL is recorded as a failure instead of aborting the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Returns the host of an `https://` URL if it is one this node may request.
/// Anything with userinfo, an IP-literal, a non-https scheme, or a host outside
/// the allowlist yields `None`.
fn allowed_host(url: &str) -> Option<&str> {
    let rest = url.strip_prefix("https://")?;
    let end = rest
        .find(|c: char| matches!(c, '/' | '?' | '#'))
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Userinfo ("host@other") and IP literals are ways to make the parsed
    // host differ from the host the transport connects to. Refuse them.
    if authority.contains('@') || authority.contains('[') {
        return None;
    }

    let host = match authority.rsplit_once(':') {
        Some((h, _port)) => h,
        None => authority,
    };
    if host.is_empty() {
        return None;
    }

    ALLOWED_HOSTS
        .iter()
        .copied()
        .find(|allowed| allowed.eq_ignore_ascii_case(host))
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            if allowed_host(&url).is_none() {
                failures.push(FetchFailure {
                    url,
                    error: "url is not an https URL on an allowed host".to_string(),
                });
                continue;
            }

            // Transport failures (timeout, error status, oversize body) come
            // back as Err values; they cost this feed, not the run.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
